class Solution {
public:
    vector<int> res;
    void go(int num, int len, int n, int k) {
        if (len == n) {
            res.push_back(num);
            return;
        }
        int last = num % 10;
        if (last + k <= 9) go(num * 10 + last + k, len + 1, n, k);
        if (k > 0 && last - k >= 0) go(num * 10 + last - k, len + 1, n, k);
    }
    vector<int> numsSameConsecDiff(int n, int k) {
        for (int d = 1; d <= 9; d++) go(d, 1, n, k);
        return res;
    }
};
